# Координаты слайдов ниже написаны в сетке SRC_ZONE; fit_zone() переносит их в DST_ZONE:
# слева — поле шаблона X5 (0.37"), снизу — над логотипом X5 (он на мастере: x 0.37–1.76", y 6.67–7.09").
SRC_ZONE = (X0, Y0, X1, Y1)            # 0.12, 1.3, 10.2, 6.9
DST_ZONE = (0.37, 1.25, 10.2, 6.5)
ZX0, ZY0, ZX1, ZY1 = DST_ZONE
SLOT_P, SLOT_H = 0.74, 0.66           # шаг и высота плашек колонки шапок
LIGHT = set()                           # слайды из light() с колонкой шапок: к ним применяется fit_zone()


def fit_zone(s):
    sx0, sy0, sx1, sy1 = SRC_ZONE
    kx = (ZX1 - ZX0) / (sx1 - sx0); ky = (ZY1 - ZY0) / (sy1 - sy0)
    for sh in s.shapes:
        if sh.is_placeholder: continue
        x, y, w, h = (v / 914400 for v in (sh.left, sh.top, sh.width, sh.height))
        if x + w > sx1 + 0.05 or y < 1.0: continue        # колонка шапок, номер слайда, заголовок
        sh.left, sh.width = Inches(ZX0 + (x - sx0) * kx), Inches(w * kx)
        sh.top, sh.height = Inches(ZY0 + (y - sy0) * ky), Inches(h * ky)


def column(s, sid):
    st = ab_pairs(sid) or {}
    for i, (k, node) in enumerate(SLOTS):
        y = ZY0 + i * SLOT_P
        a, b = st.get(k, ('—', '—')); filled = a != '—' or b != '—'
        if filled: clone(s, 'white', RX, y, RW, SLOT_H)
        else: rect(s, RX, y, RW, SLOT_H, 'F3F4F6', line='D9DDE3', radius=0.14, dash=True)
        text(s, RX + 0.15, y + 0.05, RW - 0.3, 0.22, k, size=11, color=MUTED)
        size = 15 if len(a) + len(b) <= 16 else 13
        ctext(s, RX + 0.1, y + 0.27, RW - 0.2, SLOT_H - 0.3, [(a, GREEN if filled else 'B6BCC6'), ('  /  ', 'B6BCC6'), (b, BRED if filled else 'B6BCC6')], size=size)
    my = ZY0 + 5 * SLOT_P
    minimap(s, RX, my, RW, ZY1 - my, int(sid.split('.')[0]))


def ann(sid, title, mins, screen, speech, demo=None, kind='слайд'):
    ANN.append(dict(sid=sid, title=title, mins=mins, screen=screen, speech=speech, demo=demo, kind=kind))


def finish(s, sid, screen, demo=None, title=None):
    d = SL[sid]
    if sid in LIGHT: fit_zone(s)
    s.notes_slide.notes_text_frame.text = f'[{sid} · {d["mins"]} мин]\n\n{d["Речь"]}' + (f'\n\n— — —\nДЕМО: {demo}' if demo else '')
    ann(sid, title or d['title'], d['mins'], screen, d['Речь'], demo)


def fit_title(s, limit=36):
    """Заголовок в одну строку: длиннее limit знаков — 30 pt вместо 36 (мастер: noAutofit, перенос налезает на Y0)."""
    tt = s.shapes.title
    if len(tt.text_frame.text) > limit:
        for p in tt.text_frame.paragraphs:
            for r in p.runs: r.font.size = Pt(30)


def light(sid, bg='green', title=None, col=True):
    """col=False — слайд без колонки шапок, на всю ширину; координаты тогда пишутся сразу в итоговой сетке (fit_zone не применяется)."""
    s = prs.slides.add_slide(LAY[bg])
    if col: LIGHT.add(sid)
    set_title(s, title or SL[sid]['title'])
    tt = s.shapes.title
    tt.left, tt.top, tt.width, tt.height = Inches(0.37), Inches(0.40), Inches(11.0), Inches(0.58)
    fit_title(s)
    drop_empty_placeholders(s)
    text(s, 11.4, 0.42, 1.55, 0.3, sid, size=11, color=MUTED, align='r')
    if col: column(s, sid)
    return s


def divider(n):
    nd = NODES[n]; q = NODES[n - 1]['q']
    s = dark(f'Узел {n} из 12', nd['title'], ['**Вопрос зала**', q], note=f'Разделитель узла {n} · {nd["mins"]} мин.\n\n{q}', big_size=40)
    st = 0.34; x0 = (13.333 - st * 11) / 2
    for i in range(1, 13):
        d = 0.2 if i == n else 0.12
        rect(s, x0 + st * (i - 1) - d / 2, 6.55 - d / 2, d, d, 'AADC00' if i <= n else '3F6F47', shape=MSO_SHAPE.OVAL)
    ann(f'узел {n}', nd['title'], nd['mins'], f'Тёмный слайд-разделитель: «Узел {n} из 12», название узла и вопрос, на который он отвечает; внизу ряд из 12 точек — текущий узел выделен.',
        f'Итак, вопрос. {q} (Разделитель: вопрос, которым закончился прошлый узел, звучит ещё раз — дальше узел на него отвечает. Пауза в пару секунд, пока зал читает слайд.)', kind='разделитель')


def breather(n, k):
    s = prs.slides.add_slide(LAY['white'])
    set_title(s, f'Где мы · после узла {n}')
    drop_empty_placeholders(s)
    talk_map(s, 0.47, 1.45, 12.38, 4.95, upto=n, current=n, size=10.5)
    said = {1: 'Два шага движка позади: форма и место чтения. У B восемь форм, и каждое чтение идёт через общий словарь. Серыми остались компилятор, сервер и три эпохи V8.',
            2: 'Путь объекта пройден: восемь форм → чтение через словарь → общий путь на любом ярусе. Дальше — сервер, а потом назад по времени: три эпохи V8.',
            3: 'Путь по вызовам закрыт числом на сервере, а назад по времени пройдены две эпохи: записи переехали из кода в вектор, ставка осталась. Осталось: Maglev, Turbolev и карта целиком.'}[k]
    s.notes_slide.notes_text_frame.text = 'ПЕРЕДЫШКА, 5 секунд. ' + said
    ann(f'передышка {k}', f'Где мы · после узла {n}', '0.1', f'Карта доклада целиком: шаги 1–{n} проявлены (у каждого — что у A, что у B и чем это увидеть), остальные приглушены.',
        f'Пауза на пять секунд, одна фраза: «{said}» Дать залу посмотреть на карту и выдохнуть.', kind='передышка')


